package com.flightparty.table;
import java.util.*;
/** Drawing data is bounded and the answer is redacted for the guessing seat. */
public final class SketchRules {
 private static final String[] WORDS={"太阳","月亮","雨伞","苹果","飞机","汽车","小猫","大树","房子","花朵","蛋糕","小鱼","自行车","雪人","杯子","眼镜","火车","火箭","草莓","西瓜","香蕉","葡萄","菠萝","萝卜","南瓜","蘑菇","蝴蝶","蜜蜂","蜘蛛","蜗牛","企鹅","兔子","熊猫","老虎","狮子","大象","长颈鹿","鲸鱼","海豚","乌龟","小狗","公鸡","鸭子","青蛙","恐龙","机器人","城堡","桥梁","风车","帐篷","书包","铅笔","橡皮","书本","剪刀","钥匙","锁头","闹钟","手表","电话","电视","相机","耳机","灯泡","蜡烛","椅子","桌子","沙发","冰箱","洗衣机","风扇","牙刷","毛巾","水龙头","浴缸","足球","篮球","羽毛球","网球","风筝","气球","礼物","奖杯","皇冠","钻石","戒指","手套","围巾","帽子","鞋子","袜子","衬衫","裙子","牛仔裤","汉堡","披萨","面包","冰淇淋","甜甜圈","寿司","饺子","面条","雨滴","彩虹","雪花","闪电","云朵","星星","火山","海浪","沙滩","瀑布"};
 public static GridRules.State start(){return round(new int[2],1,0);}
 private static GridRules.State round(int[] points,int turn,int n){return new GridRules.State("draw",points,turn,0,false,n,WORDS[new java.security.SecureRandom().nextInt(WORDS.length)],List.of());}
 public static GridRules.State computer(GridRules.State s){int n=new java.security.SecureRandom().nextInt(3);String line=n==0?"500,180,220,780,780,780,500,180":n==1?"250,250,750,250,750,750,250,750,250,250":"";if(n==2){var pts=new ArrayList<String>();for(int i=0;i<=48;i++){pts.add(""+Math.round(500+280*Math.cos(i*Math.PI/24)));pts.add(""+Math.round(500+280*Math.sin(i*Math.PI/24)));}line=String.join(",",pts);}return new GridRules.State("draw",s.cells(),s.turn(),0,false,s.moves(),new String[]{"三角形","正方形","圆形"}[n],List.of(line));}
 public static GridRules.State visible(GridRules.State s,int seat){return new GridRules.State(s.game(),s.cells(),s.turn(),s.winner(),s.over(),s.moves(),s.over()||seat==s.turn()?s.fen():"?".repeat(s.fen().length()),s.history());}
 public static GridRules.State advance(GridRules.State s,boolean correct){int[] points=s.cells().clone();if(correct){points[s.turn()-1]++;points[2-s.turn()]+=2;}int n=s.moves()+1;if(n==6)return new GridRules.State("draw",points,3-s.turn(),points[0]==points[1]?0:points[0]>points[1]?1:2,true,n,s.fen(),s.history());return round(points,3-s.turn(),n);}
 public static GridRules.State act(GridRules.State s,int actor,String action,String text,List<Integer> points){if(s.over())throw new IllegalStateException();if("guess".equals(action)){if(actor==s.turn()||text==null||text.length()>40)throw new IllegalArgumentException();String guess=java.text.Normalizer.normalize(text.trim(),java.text.Normalizer.Form.NFKC);return guess.equalsIgnoreCase(s.fen())?advance(s,true):s;}if(actor!=s.turn())throw new IllegalArgumentException();if("clear".equals(action))return new GridRules.State("draw",s.cells(),s.turn(),0,false,s.moves(),s.fen(),List.of());if(!"stroke".equals(action)||points==null||points.size()<4||points.size()>600||points.size()%2!=0||s.history().size()>=100||points.stream().anyMatch(p->p==null||p<0||p>1000))throw new IllegalArgumentException();var history=new ArrayList<>(s.history());history.add(String.join(",",points.stream().map(Object::toString).toList()));return new GridRules.State("draw",s.cells(),s.turn(),0,false,s.moves(),s.fen(),history);}
}
